int wmain(int argc,wchar_t** argv){if(argc<2)return ERROR_INVALID_PARAMETER;std::wstring command=argv[1];if(command==L"--start-service"){SC_HANDLE manager=OpenSCManagerW(nullptr,nullptr,SC_MANAGER_CONNECT);if(!manager)return GetLastError();SC_HANDLE service=OpenServiceW(manager,ServiceName,SERVICE_START);DWORD error=service&&StartServiceW(service,0,nullptr)?0:GetLastError();if(service)CloseServiceHandle(service);CloseServiceHandle(manager);return error==ERROR_SERVICE_ALREADY_RUNNING?0:error;}if(command==L"--install-service")return install();if(command==L"--stop-service")return manage(false);if(command==L"--uninstall-service")return manage(true);if(command==L"--service"){SERVICE_TABLE_ENTRYW table[]={{const_cast<LPWSTR>(ServiceName),serviceMain},{nullptr,nullptr}};return StartServiceCtrlDispatcherW(table)?0:static_cast<int>(GetLastError());}return ERROR_INVALID_PARAMETER;}
